        .progress-container {
            margin: 16px 0;
        }

        .progress-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 8px;
        }

        .progress-title {
            color: var(--text-secondary);
            font-size: 13px;
            font-weight: 500;
        }

        .progress-value {
            color: var(--text-primary);
            font-size: 13px;
            font-weight: 600;
        }

        .progress-bar {
            width: 100%;
            height: 8px;
            background: var(--bg-secondary);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .progress-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            overflow: hidden;
        }

        .progress-pink { background: linear-gradient(90deg, var(--medical-pink), var(--medical-light-pink)); }
        .progress-green { background: linear-gradient(90deg, #4ade80, #86efac); }
        .progress-red { background: linear-gradient(90deg, var(--medical-red), #fca5a5); }
        .progress-orange { background: linear-gradient(90deg, var(--medical-orange), #fdba74); }

        @media (max-width: 768px) {
            .medical-nav {
                grid-template-columns: repeat(3, 1fr);
            }

            .nav-item {
                padding: 12px 8px;
                font-size: 12px;
            }

            .info-grid {
                grid-template-columns: 1fr;
                gap: 16px;
            }

            .medical-content {
                padding: 16px;
            }

            .wardrobe-grid {
                grid-template-columns: repeat(3, 1fr);
            }
        }
    </style>
